    let id: String
    let team: String
    let headcount: Int
    let joiners: Int
    let leavers: Int
    let remote: Bool
}

@Environment(\.monarchTheme) private var theme
@State private var period = MonarchPeriod(MonarchPeriodPreset(rawValue: {{periods.presets.0}}) ?? .last30Days)

private let rows = [
    TeamRow(id: {{rows.0.team}}, team: {{rows.0.team}}, headcount: {{rows.0.headcount}}, joiners: {{rows.0.joiners}}, leavers: {{rows.0.leavers}}, remote: {{rows.0.remote}}),
    TeamRow(id: {{rows.1.team}}, team: {{rows.1.team}}, headcount: {{rows.1.headcount}}, joiners: {{rows.1.joiners}}, leavers: {{rows.1.leavers}}, remote: {{rows.1.remote}}),
    TeamRow(id: {{rows.2.team}}, team: {{rows.2.team}}, headcount: {{rows.2.headcount}}, joiners: {{rows.2.joiners}}, leavers: {{rows.2.leavers}}, remote: {{rows.2.remote}}),
]

private var generated: String {
    let at = {{generatedAt|date}}
    let style = Date.FormatStyle(locale: Locale(identifier: {{locale}}), timeZone: TimeZone(identifier: {{timeZone}}) ?? .gmt)
