}

examples.setup:
struct TeamRow: Identifiable, Sendable {
    let id: String
    let team: String
    let headcount: Int
    let joiners: Int
    let leavers: Int
    let remote: Bool
}

@Environment(\.monarchTheme) private var theme
@State private var period = MonarchPeriod(MonarchPeriodPreset(rawValue: "30d") ?? .last30Days)

private let rows = [
    TeamRow(id: "Design", team: "Design", headcount: 14, joiners: 2, leavers: 0, remote: true),
    TeamRow(id: "Engineering", team: "Engineering", headcount: 41, joiners: 5, leavers: 1, remote: true),
    TeamRow(id: "Support", team: "Support", headcount: 18, joiners: 1, leavers: 2, remote: false),
]

private var generated: String {
    let at = Date(timeIntervalSince1970: 1_794_045_600)
    let style = Date.FormatStyle(locale: Locale(identifier: "en-GB"), timeZone: TimeZone(identifier: "UTC") ?? .gmt)
    return "Generated \(at.formatted(style.year().month(.abbreviated).day())), \(at.formatted(style.hour().minute()))"
}

